 public function recordMarketplaceClaim(string$requestId,string$merchantId,string$userId,array$metadata=[]):array{$existing=$this->marketplaceClaim($requestId);if($existing!==null)return$existing;$id=RandomId::make();$s=$this->pdo->prepare('INSERT INTO marketplace_claims(id,loan_request_id,merchant_id,claimed_by_user_id,metadata_json) VALUES(:id,:r,:m,:u,:meta)');$s->execute([':id'=>$id,':r'=>$requestId,':m'=>$merchantId,':u'=>$userId,':meta'=>$metadata!==[]?Json::encode($metadata):null]);$this->event('loan_request',$requestId,'marketplace.claimed',$userId,'allowed',['merchant_id'=>$merchantId]);return$this->marketplaceClaim($requestId)??throw new RuntimeException('ثبت پذیرش بازار قابل بازیابی نیست.');}
 public function marketplaceClaim(string$requestId):?array{$s=$this->pdo->prepare('SELECT * FROM marketplace_claims WHERE loan_request_id=:r LIMIT 1');$s->execute([':r'=>$requestId]);$r=$s->fetch();if(!is_array($r))return null;$r['metadata']=Json::decode((string)($r['metadata_json']??''));unset($r['metadata_json']);return$r;}
 public function createInvitation(string$merchantId,string$actor,?string$expiresAt=null):array{$plain='N'.strtoupper(bin2hex(random_bytes(8)));$hash=hash('sha256',$plain);$id=RandomId::make();$s=$this->pdo->prepare('INSERT INTO merchant_invitations(id,merchant_id,invitation_code_hash,created_by_user_id,expires_at) VALUES(:id,:m,:h,:a,:e)');$s->execute([':id'=>$id,':m'=>$merchantId,':h'=>$hash,':a'=>$actor,':e'=>$expiresAt]);$this->event('merchant',$merchantId,'merchant.invitation.created',$actor,'allowed',['invitation_id'=>$id,'expires_at'=>$expiresAt]);return['id'=>$id,'merchant_id'=>$merchantId,'code'=>$plain,'status'=>'active','expires_at'=>$expiresAt];}
 public function redeemInvitation(string$code,string$userId):?array{$hash=hash('sha256',trim($code));$this->pdo->beginTransaction();try{$s=$this->pdo->prepare("SELECT * FROM merchant_invitations WHERE invitation_code_hash=:h FOR UPDATE");$s->execute([':h'=>$hash]);$r=$s->fetch();if(!is_array($r)||$r['status']!=='active'||($r['expires_at']!==null&&$r['expires_at']<gmdate('Y-m-d H:i:s'))){$this->pdo->rollBack();return null;}$u=$this->pdo->prepare("UPDATE merchant_invitations SET status='used',used_by_user_id=:u,used_at=NOW(6) WHERE id=:id AND status='active'");$u->execute([':u'=>$userId,':id'=>$r['id']]);if($u->rowCount()!==1){$this->pdo->rollBack();return null;}$this->pdo->commit();$this->event('merchant',(string)$r['merchant_id'],'merchant.invitation.used',$userId,'allowed',['invitation_id'=>$r['id']]);$r['code']=null;$r['status']='used';return$r;}catch(Throwable$e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw$e;}}
 public function events(string$type,string$id):array{$s=$this->pdo->prepare('SELECT * FROM partner_events WHERE aggregate_type=:t AND aggregate_id=:id ORDER BY created_at DESC LIMIT 250');$s->execute([':t'=>$type,':id'=>$id]);$rows=$s->fetchAll();foreach($rows as&$r){$r['details']=Json::decode((string)($r['details_json']??''));unset($r['details_json']);}return$rows;}
 public function event(string$type,?string$id,string$event,?string$actor,string$result,array$details=[]):void{$meta=RequestContext::auditMeta();$s=$this->pdo->prepare('INSERT INTO partner_events(id,aggregate_type,aggregate_id,event_type,actor_user_id,result,details_json,request_id,caller_service) VALUES(:id,:t,:a,:e,:u,:r,:d,:req,:caller)');$s->execute([':id'=>RandomId::make(),':t'=>$type,':a'=>$id,':e'=>$event,':u'=>$actor,':r'=>$result,':d'=>$details!==[]?Json::encode($details):null,':req'=>$meta['request_id']??null,':caller'=>$meta['caller_service']??null]);}
 private function decodeMerchant(array$r):array{$r['financial_settings']=Json::decode((string)($r['financial_settings_json']??''));$r['metadata']=Json::decode((string)($r['metadata_json']??''));unset($r['financial_settings_json'],$r['metadata_json']);return$r;}
 private function decodeCooperation(array$r):array{$r['data']=Json::decode((string)($r['data_json']??''));unset($r['data_json'],$r['otp_hash'],$r['contract_token_hash']);$r['document_policy']=\Babanoell\Partners\Domain\CooperationFormDefinition::documentPolicy($r);$r['form_catalog']=\Babanoell\Partners\Domain\CooperationFormDefinition::catalog();return$r;}
 public function correctCooperationProfile(string $id,string $actor,array $fields,int $expectedVersion,string $reason,bool $acknowledgeSigned):array
 {
  if($expectedVersion<1||mb_strlen(trim($reason))<10||mb_strlen($reason)>1000)throw new \InvalidArgumentException('نسخه رکورد و دلیل اصلاح حداقل ۱۰ کاراکتری الزامی است.');
  $allowed=['full_name','father_name','company_name','legal_name','trade_name','national_code','applicant_id_number','national_id','registration_number','mobile','phone','postal_code','address','activity','representative_name'];
  if($fields===[]||array_diff(array_keys($fields),$allowed)!==[])throw new \InvalidArgumentException('فیلدهای اصلاح درخواست همکاری مجاز نیستند.');
  $this->pdo->beginTransaction();
  try {
   $q=$this->pdo->prepare('SELECT * FROM cooperation_requests WHERE id=:id FOR UPDATE');$q->execute([':id'=>$id]);$old=$q->fetch(PDO::FETCH_ASSOC);
   if(!is_array($old))throw new RuntimeException('درخواست همکاری پیدا نشد.');
   if((int)$old['row_version']!==$expectedVersion)throw new RuntimeException('درخواست همکاری همزمان تغییر کرده است؛ صفحه را تازه‌سازی کنید.');
   $signed=(string)($old['contract_signed_status']??'pending')==='signed';
   if(($signed||in_array((string)$old['status'],['approved','archived'],true))&&!$acknowledgeSigned)throw new RuntimeException('برای درخواست تاییدشده یا دارای قرارداد امضاشده، تأیید آگاهانه لازم است؛ قرارداد امضاشده تغییر نخواهد کرد.');
   $data=Json::decode((string)($old['data_json']??''));if(!is_array($data))$data=[];
   $before=[];$after=[];
   foreach($fields as$key=>$raw){if(!in_array($key,$allowed,true))continue;
    $value=$raw===null?'':trim((string)$raw);$limit=$key==='address'?2000:190;
    if(mb_strlen($value)>$limit)throw new \InvalidArgumentException('طول داده واردشده بیش از حد مجاز است.');
    if((string)($data[$key]??'')===$value)continue;
    $before[$key]=$data[$key]??null;$after[$key]=$value===''?null:$value;
    if($value==='')unset($data[$key]);else $data[$key]=$value;
   }
   if($after===[])throw new \InvalidArgumentException('هیچ تغییری در فیلدهای انتخاب‌شده وجود ندارد.');
   if(isset($data['_form']))$data=\Babanoell\Partners\Domain\CooperationFormDefinition::patchAliases((string)$old['request_type'],$data,$after);
   $u=$this->pdo->prepare('UPDATE cooperation_requests SET data_json=:data,row_version=row_version+1 WHERE id=:id AND row_version=:v');
   $u->execute([':data'=>Json::encode($data),':id'=>$id,':v'=>$expectedVersion]);
   if($u->rowCount()!==1)throw new RuntimeException('تداخل ویرایش همزمان رخ داد.');
   $log=$this->pdo->prepare('INSERT INTO cooperation_profile_corrections(id,cooperation_request_id,actor_user_id,reason,changed_fields_json,before_json,after_json,row_version_before,row_version_after) VALUES(:id,:request,:actor,:reason,:fields,:before,:after,:v,:next)');
   $log->execute([':id'=>RandomId::make(),':request'=>$id,':actor'=>$actor,':reason'=>$reason,':fields'=>Json::encode(array_keys($after)),':before'=>Json::encode($before),':after'=>Json::encode($after),':v'=>$expectedVersion,':next'=>$expectedVersion+1]);
   $this->event('cooperation_request',$id,'cooperation.profile_corrected',$actor,'allowed',['fields'=>array_keys($after),'version'=>$expectedVersion+1]);
   $this->pdo->commit();
  }catch(Throwable $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw$e;}
  return $this->getCooperation($id)??throw new RuntimeException('درخواست همکاری قابل بازیابی نیست.');
 }
 public function cooperationCorrections(string $id):array
 {
  $s=$this->pdo->prepare('SELECT * FROM cooperation_profile_corrections WHERE cooperation_request_id=:id ORDER BY created_at DESC,id DESC LIMIT 100');$s->execute([':id'=>$id]);$rows=$s->fetchAll();
  foreach($rows as &$r){foreach(['changed_fields_json','before_json','after_json'] as $k){$r[substr($k,0,-5)]=Json::decode((string)($r[$k]??''));unset($r[$k]);}}return$rows;
 }
 public function cooperationByLegacyId(int $legacyId):?array
 {
  $s=$this->pdo->prepare('SELECT id FROM cooperation_requests WHERE legacy_id=:legacy LIMIT 1');$s->execute([':legacy'=>$legacyId]);$id=$s->fetchColumn();return is_string($id)?$this->getCooperation($id):null;
 }

